// Rule checks (code) before the judge: format, link, opt-out line, and NO number that isn't in the brief.
const b = $('Build brief (rules)').item.json;
const prev = $('Build brief (rules)').item.json;
const d = $json.output || {};
const issues = [];
if (!d.body) issues.push('Model returned no draft');
const body = String(d.body || ''), subject = String(d.subject || '');
const words = s => s.trim().split(/\s+/).filter(Boolean).length;
if (b.channel === 'Email') {
  if (words(subject) < 3 || words(subject) > 7) issues.push(`Subject has ${words(subject)} words (3-7)`);
  const bodyWords = words(body.replace(b.bookingLink, ''));
  if (bodyWords < 50 || bodyWords > 130) issues.push(`Body has ${bodyWords} words (60-110 + sign-off)`);
  if (!body.includes(b.bookingLink)) issues.push('Booking link missing or altered');
  if (!/won't follow up|melde ich mich nicht wieder/i.test(body)) issues.push('Opt-out line missing');
  if (!body.includes('noahhofmann.com/waypoint')) issues.push('Sign-off missing');
} else {
  if (body.length > 300) issues.push(`LinkedIn note has ${body.length} characters (max 280)`);
  if (/https?:\/\//.test(body)) issues.push('LinkedIn note must not contain a link');
}
if (!body.includes(b.first)) issues.push(`Recipient first name "${b.first}" not used`);
const HYPE = /(revolutionary|game[- ]changing|synergy|leverage|unlock|skyrocket|hope this (email )?finds you)/i;
if (HYPE.test(body + ' ' + subject)) issues.push('Hype or filler phrase: ' + (body + ' ' + subject).match(HYPE)[0]);
// Every number in the draft must appear in the brief (catches invented metrics)
const allowed = b.allowedText.replace(/[.,\s]/g, '');
const nums = (subject + ' ' + body.replace(b.bookingLink, '')).match(/\d[\d.,]*/g) || [];
const bad = [...new Set(nums.map(n => n.replace(/[.,]$/, '')))].filter(n => n.length && !allowed.includes(n.replace(/[.,]/g, '')) && !['30', '1', '2', '3'].includes(n));
if (bad.length) issues.push('Numbers not in the brief: ' + bad.join(', '));
return { json: { ...prev, draft: { subject: b.channel === 'Email' ? subject : '', body, claims: d.claims || [] }, ruleIssues: issues } };

// Combine rule checks and judge. Pass only if both are clean.
const p = $('Check rules 1').item.json;
const j = $json.output || { pass: false, issues: ['Judge returned no result'] };
const judgeIssues = [...(j.unsupported_claims || []).map(x => 'Unsupported: ' + x), ...(j.issues || [])];
const pass = p.ruleIssues.length === 0 && j.pass === true && !(j.unsupported_claims || []).length;
const notes = [
  `Attempt ${p.attempt}: ${pass ? 'PASS' : 'FAIL'}` + (j.scores ? ` (grounded ${j.scores.grounded}, specific ${j.scores.specific}, tone ${j.scores.tone})` : ''),
  ...p.ruleIssues.map(x => 'Rule: ' + x), ...judgeIssues.map(x => 'Judge: ' + x),
  ...(j.suggestions || []).slice(0, 3).map(x => 'Suggestion: ' + x)
].join('\n');
return { json: { ...p, pass, judgeNotes: (p.judgeNotes ? p.judgeNotes + '\n' : '') + notes,
  feedback: [...p.ruleIssues, ...judgeIssues].join('\n') } };

