// Combine rule checks and judge. Pass only if both are clean.
const p = $('Check rules 2').item.json;
const j = $json.output || { pass: false, issues: ['Judge returned no result'] };
const judgeIssues = [...(j.unsupported_claims || []).map(x => 'Unsupported: ' + x), ...(j.issues || [])];
const pass = p.ruleIssues.length === 0 && j.pass === true && !(j.unsupported_claims || []).length;
const notes = [
  `Attempt ${p.attempt}: ${pass ? 'PASS' : 'FAIL'}` + (j.scores ? ` (grounded ${j.scores.grounded}, specific ${j.scores.specific}, tone ${j.scores.tone})` : ''),
  ...p.ruleIssues.map(x => 'Rule: ' + x), ...judgeIssues.map(x => 'Judge: ' + x),
  ...(j.suggestions || []).slice(0, 3).map(x => 'Suggestion: ' + x)
].join('\n');
return { json: { ...p, pass, judgeNotes: (p.judgeNotes ? p.judgeNotes + '\n' : '') + notes,
  feedback: [...p.ruleIssues, ...judgeIssues].join('\n') } };

// Write the result to Notion. Pass -> Draft ready (goes to Telegram approval in 50).
// Fail after the retry -> Check manually, with every issue in Judge notes. Nothing is ever sent from here.
const r = $json;
const t = s => [{ type: 'text', text: { content: String(s ?? '').slice(0, 1990) } }];
const props = {
  'Status': { status: { name: r.pass ? 'Draft ready' : 'Check manually' } },
  'Draft subject': { rich_text: t(r.draft?.subject || '') },
  'Draft body': { rich_text: t(r.draft?.body || '') },
  'Draft version': { number: (r.draftVersion || 0) + 1 },
  'Judge result': { select: { name: r.pass ? 'Pass' : 'Fail' } },
  'Judge notes': { rich_text: t(r.judgeNotes) },
  'Channel': { select: { name: r.channel } },
  'Offer': { rich_text: t(r.offer) },
  'Draft language': { select: { name: r.language } },
  'Angle': { select: { name: 'Funding trigger' } }
};
if (r.channel === 'Email') props['Booking link'] = { url: r.bookingLink };
return { json: { contactPageId: r.contactPageId, name: r.name, company: r.company, channel: r.channel, pass: r.pass, attempts: r.attempt,
  notionBody: { properties: props } } };

// Summary for the orchestrator / manual run.
const rows = $('Build draft update').all().map(i => i.json);
return [{ json: { drafted: rows.length, passed: rows.filter(r => r.pass).length,
  firstTry: rows.filter(r => r.pass && r.attempts === 1).length, failed: rows.filter(r => !r.pass).length,
  drafts: rows.map(r => ({ name: r.name, company: r.company, channel: r.channel, pass: r.pass, attempts: r.attempts })) } }];
